with products_by_supplier as (select supplier_id, round(avg(price), 2) avg_price, round((100 * sum(case when brand = 'Stark' then 1 else 0 end)) / count(*), 1) pct_stark from products where launch_date <= '2023-03-16' group by supplier_id) select s.rating, s.city, pbs.avg_price, pbs.pct_stark from suppliers s left join products_by_supplier pbs on s.id = pbs.supplier_id where pbs.pct_stark >= 66
